/// A layer's split-K counters (Exl3Linear.counters) by its trellis words.
pub const Counter = struct { words: u64, ptr: u64 };

pub fn counterOf(ch: *const Chunk, l: weights.Linear) !u64 {
    for (ch.counters[0..ch.n_counters]) |c| if (c.words == l.words) return c.ptr;
    return error.NoCounters;
}

/// The rows a mixed pack's plain (cuBLAS) linear runs over: `m`, padded to the engine's plain-rows setting and never
/// beyond a round's rows (the buffers are sized for those). cuBLAS picks its kernel and split-K from the GEMM's shape
/// and its rounding follows the pick, so a fixed shape keeps a token's bits the same whether it is decoded alone,
/// beside other streams, or under the draft block (TF_DS_PLAIN_ROWS=0 turns the padding off).
fn plainRows(e: *const Engine, m: usize) usize {
    if (e.plain_rows <= m) return m;
    return @min(e.plain_rows, e.round_rows);
}

/// Exl3Group(ls) on m (1..128) rows (linear.py): one rot_many launch rotating every layer's input rows xs[i] (bf16,
/// row stride ldxs[i]) into the group's buffer, then a glinear launch for each (bits, warps) set, outputs into outs[i]
/// (row stride ldos[i], dtype types[i]); programmatic dependent launches, split-K partials dropped from L2 (the served
/// TF_EXL3_PDL and TF_EXL3_L2_DISCARD).
pub fn grouped(e: *const Engine, ch: *const Chunk, m: usize, ls: []const weights.Linear, xs: []const u64, ldxs: []const usize, outs: []const u64, ldos: []const usize, types: []const exl3_linear.DType) !void {
    if (m == 0 or m > 128 or ls.len > 8) return error.NotADecodeWindow;
    // The group's EXL3 linears go through rot_many + glinear; a mixed pack's plain ones run on cuBLAS after them
    // (the same stream, so they start after glinear has read the rotated rows in ch.gxh).
    var calls: [8]exl3_linear.Call = undefined;
    var plain: [8]usize = undefined;
    var n_calls: usize = 0;
    var n_plain: usize = 0;
    var off: usize = 0;
    for (ls, 0..) |l, i| {
        if (l.plain != 0) {
            plain[n_plain] = i;
            n_plain += 1;
            continue;
        }
        calls[n_calls] = .{ .layer = l, .x = xs[i], .ldx = @intCast(ldxs[i]), .x_dtype = .bf16, .xh = ch.gxh + off * 2, .y = outs[i], .ldy = @intCast(ldos[i]), .y_dtype = types[i], .counters = try counterOf(ch, l) };
        off += m * l.k;
        n_calls += 1;
    }
    if (n_calls > 0) {
        try exl3_linear.rotMany(e.lin, e.s, calls[0..n_calls], m, true);
        try exl3_linear.glinear(e.lin, e.s, calls[0..n_calls], m, ch.gz, true, true);
    }
    const mp = plainRows(e, m);
    for (plain[0..n_plain]) |i| {
        const l = ls[i];
        if (ldxs[i] != @as(usize, l.k) or ldos[i] != @as(usize, l.n)) return error.UnsupportedPlainLinear;
        if (types[i] == .bf16) {
            try e.blas.linearBf16(xs[i], l.plain, outs[i], mp, @as(usize, l.k), @as(usize, l.n));
        } else {
            try e.blas.linearBf16(xs[i], l.plain, ch.plain_tmp, mp, @as(usize, l.k), @as(usize, l.n));
            try e.ops.toF32(e.s, ch.plain_tmp, outs[i], mp * @as(usize, l.n));
        }
    }
}

/// Exl3Group.rotated on m rows already rotated into each call's xh (a kernel that folds the rotation in wrote them):
/// the glinear launches alone, each call's counters and folds as given.
pub fn groupedRotated(e: *const Engine, ch: *const Chunk, m: usize, calls: []exl3_linear.Call) !void {
    if (m == 0 or m > 128 or calls.len > exl3_linear.gmax) return error.NotADecodeWindow;
    // The rows are already rotated for the EXL3 linears (a kernel wrote each call's xh). A mixed pack's plain linear
    // takes the unrotated rows: its call carries x, not xh.
    var exl3: [exl3_linear.gmax]exl3_linear.Call = undefined;
    var plain: [exl3_linear.gmax]exl3_linear.Call = undefined;
    var n_exl3: usize = 0;
    var n_plain: usize = 0;
    for (calls) |c| {
        if (c.layer.plain != 0) {
            plain[n_plain] = c;
            n_plain += 1;
        } else {
            exl3[n_exl3] = c;
            n_exl3 += 1;
        }
    }
    for (exl3[0..n_exl3]) |*c| c.counters = try counterOf(ch, c.layer);
    if (n_exl3 > 0) try exl3_linear.glinear(e.lin, e.s, exl3[0..n_exl3], m, ch.gz, true, true);
    const mp = plainRows(e, m);
    for (plain[0..n_plain]) |c| {
        if (c.x == 0 or c.xh != 0 or c.ldx != @as(i64, c.layer.k) or c.ldy != @as(i64, c.layer.n)) return error.UnsupportedPlainLinear;
        if (c.y_dtype == .bf16) {
            try e.blas.linearBf16(c.x, c.layer.plain, c.y, mp, @as(usize, c.layer.k), @as(usize, c.layer.n));
        } else {
            try e.blas.linearBf16(c.x, c.layer.plain, ch.plain_tmp, mp, @as(usize, c.layer.k), @as(usize, c.layer.n));
            try e.ops.toF32(e.s, ch.plain_tmp, c.y, mp * @as(usize, c.layer.n));
        }
    }
}

/// The pool's compressed-attention caches (model.py PoolCache: comp, index_k, comp_raw), by kv-source layer: the
/// compressed latents as packed FP4 (codes [rows, head_dim / 2], E8M0 scales [rows, head_dim / 16]), the index keys
/// (codes [rows, index_head_dim / 2], scales [rows, index_head_dim / 32], 127 when unwritten) over `cap` positions of
/// streams' extents (rows = cap / ratio + 2), and, at ratio 2, each slot's positional store of the compressor's raw kv
/// and scores (fp32 [RAW, head_dim] each, `slots` of them). One stream's caches (SeqCache) are a view.
pub const Caches = struct {
    comp_codes: [64]u64 = @splat(0),
    comp_scales: [64]u64 = @splat(0),
    idx_codes: [64]u64 = @splat(0),
    idx_scales: [64]u64 = @splat(0),
    raw_kv: [64]u64 = @splat(0),
