            const want = passDrafts(depths[n], base, r.follow.len, self.wide_kept, room);
            asked[n] = l;
            steps = @max(steps, want);
            n += 1;
        }
        if (n == 0) return;
        const kv = self.streams.fetchRemove(s) orelse {
            if (self.kv) |k| k.forgetKey(@intFromPtr(s)); // (a request that never placed: its refusal record goes)
            return;
        };
        self.used[kv.value.slot] = false;
        if (self.kv) |k| k.release(kv.value.id) catch |err| std.log.err("dsv41: the parts' planner kept a released stream: {s}", .{@errorName(err)});
    }
};

/// TF_DS_DRAFT_BLOCK: the drafts a stream's pass runs for it, of the `asked` it holds for the round loop: more than
/// the checkpoint's block (`base`) only when its last round kept at least `wide_kept` rows (its drafts are landing)
/// and a round has room for that many of its drafts (`room`: a round's rows shared evenly by the pass's streams, less
/// the pending row); the checkpoint's block otherwise. A stream asked no more than the block runs what it asked.
pub fn passDrafts(asked: usize, base: usize, kept: usize, wide_kept: usize, room: usize) usize {
    if (asked <= base) return asked;
    return if (kept >= wide_kept and room > base) @min(asked, room) else base;
}

/// The drafts a stream holds after a pass of `steps` drafts: every one of the `hold` the round loop asked, and the
/// count it returns is `hold` (the round loop sizes its window by the drafts it asked: a shorter count refuses the
/// window, HeldMismatch). Those the pass ran keep its tokens and confidences; the rest (the stream's pass stayed under
/// its asked depth) hold the last draft's token at no_chance, a confidence whose sigmoid is 0, so the allocation never
/// spends a row on them, and a verify of one would only reject it.
pub fn holdDrafts(held: []u32, confs: []f32, hold: usize, steps: usize, drafts: []const i64, pass_confs: []const f32) usize {
    for (0..hold) |j| {
        if (j < steps) {
            held[j] = @intCast(drafts[j]);
            confs[j] = pass_confs[j];
        } else {
            held[j] = held[steps - 1];
            confs[j] = no_chance;
        }
    }
    return hold;
}

